// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Private_Bank, Log} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    Private_Bank c;
    function setUp() public { c = new Private_Bank(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        actor = address(uint160(uint256(keccak256(abi.encode(actor))) | 1));
        amount = bound(amount, c.MinDeposit() + 1, type(uint128).max);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Deposit{value: amount}();

        uint256 balBefore = c.balances(actor);
        assertTrue(balBefore == amount);

        uint256 contractBefore = address(c).balance;

        vm.prank(actor);
        (bool ok,) = address(c).call{value: 0}(abi.encodeWithSignature("CashOut(uint256)", balBefore));
        assertTrue(ok);

        uint256 balAfter = c.balances(actor);
        uint256 contractAfter = address(c).balance;

        assertTrue(balAfter == balBefore - amount && contractAfter == contractBefore - amount);
    }
}
